"""Question-specific Russian lessons and formative/exam tasks for modules 2–14."""
from module1_content import q

TOPICS = {}

def C(prompt, options, correct, explanation):
    return ('choice', prompt, options, [str(correct)], explanation)

def M(prompt, options, correct, explanation):
    return ('multi', prompt, options, [str(i) for i in correct], explanation)

def O(prompt, options, correct, explanation):
    return ('order', prompt, options, [str(i) for i in correct], explanation)

def N(prompt, correct, explanation):
    return ('text', prompt, [], [str(correct).casefold()], explanation)

def L(number, title, short, mechanism, example, pitfall, tasks):
    assert len(tasks)==4
    questions=[]
    for i,(kind,prompt,options,answer,explanation) in enumerate(tasks):
        question=q(f't{number}-{i+1}',kind,prompt,options,answer,explanation,
                   'Вернитесь к примеру урока: '+example)
        question['source']=number
        questions.append(question)
    TOPICS[number]=dict(id=f't{number}',source=number,title=title,minutes=5,visual='course',
        lead=short,blocks=[['Как это работает',mechanism],['Пример и проверка',example],['Что сказать на экзамене',short]],
        summary=short+' '+mechanism,pitfall=pitfall,questions=questions[:3],exam=questions[3])

# Module 2 — Ethernet and transmission media.
L(17,'Кадр Ethernet и соединение PPP',
 'Ethernet передаёт кадры в локальной сети с MAC-адресацией. PPP организует канальное соединение «точка — точка», согласует параметры линии и сетевых протоколов.',
 'В Ethernet коммутатор изучает MAC источника на входном порту. Известный unicast отправляется на соответствующий другой порт; неизвестный — на остальные порты своей VLAN. Broadcast также ограничен VLAN. PPP использует LCP для настройки канала, а NCP — для параметров сетевого уровня; аутентификация возможна, но не означает шифрование.',
 'ПК A подключён к порту 1, B — к порту 2. После кадра от A таблица содержит A → 1. Если B ещё неизвестен, первый кадр к нему распространяется по остальным портам VLAN. После ответа B коммутатор изучит B → 2.',
 'FCS обнаруживает повреждение кадра, но не шифрует данные и не исправляет все ошибки.',[
 C('Какой адрес коммутатор изучает из пришедшего кадра?',['MAC назначения','MAC источника','IP шлюза'],1,'MAC источника связывается с входным портом.'),
 C('Что делает LCP в PPP?',['Согласует параметры канала','Выдаёт имена DNS','Шифрует любой трафик'],0,'LCP устанавливает и контролирует PPP-канал. Параметры сетевых протоколов согласуются через NCP.'),
 O('Первый обмен A и неизвестного B: восстановите порядок.',['Ответ B и изучение его порта','Изучение A на входном порту','Распространение кадра к неизвестному B'],[1,2,0],'Сначала изучается источник A, затем ищется назначение B, затем ответ позволяет изучить B.'),
 C('MAC B известен на порту 2; кадр от A пришёл на порт 1. Куда его передать?',['На порт 2','На все порты Интернета','Обратно только в порт 1'],0,'Известный unicast пересылается на найденный порт своей VLAN.')])
L(19,'Медь, оптика или радио?',
 'Среда передачи переносит сигналы: медь — электрические, оптика — световые, радио — электромагнитные волны в пространстве. Выбор зависит от расстояния, скорости, помех, стоимости и подвижности узлов.',
 'Витая пара удобна для рабочих мест и может передавать питание PoE при совместимом оборудовании. Оптика устойчива к электромагнитным помехам и подходит для длинных линий, но требует подходящих трансиверов и аккуратной работы. Радио обеспечивает мобильность, однако использует общую среду и зависит от помех и покрытия.',
 'Для ноутбуков переговорной подходит Wi-Fi; для стационарных рабочих мест — Ethernet по витой паре; для линии между зданиями — подходящая оптика. Для типичного медного Ethernet-канала учитывают предел 100 м с учётом патч-кордов, а не только кабеля в стене.',
 'Скорость не определяется одним материалом: важны стандарт, длина, разъёмы и оба интерфейса.',[
 C('Нужна мобильность сотрудников внутри офиса. Какая среда решает эту задачу?',['Только коаксиал','Радиоканал Wi-Fi','Только одномодовое волокно'],1,'Радиоканал позволяет перемещаться в зоне покрытия.'),
 M('Что нужно оценить при выборе линии?',['Расстояние','Уровень помех','Только цвет кабеля'],[0,1],'Длина и среда эксплуатации влияют на допустимый тип канала и оборудования.'),
 C('Требуется передать питание PoE и данные к точке доступа. Что обычно используют?',['Совместимый медный Ethernet','Одно пассивное оптоволокно','DNS'],0,'PoE использует проводники медной линии. По самому стеклянному волокну электрическое питание не передаётся.'),
 C('Два здания разделены 300 м. Какой вариант разумнее обычной витой пары без промежуточного оборудования?',['Подходящая оптическая линия','Любая витая пара независимо от длины','Bluetooth без проверки дальности'],0,'Оптический стандарт и трансиверы выбирают по длине и требуемой скорости.')])
L(20,'Как свет переносит данные',
 'Оптоволоконная линия передаёт информацию модулированным светом по сердцевине волокна. Источник, волокно и приёмник должны быть совместимы по типу, длине волны и оптическому бюджету.',
 'Одномодовое волокно применяется в том числе на больших расстояниях; многомодовое часто используется на коротких линиях внутри зданий и ЦОД. Дальность зависит от конкретного стандарта и трансиверов. Затухание, грязные разъёмы, изгибы и несовместимые модули могут нарушить связь.',
 'Перед соединением двух коммутаторов сопоставьте SM/MM, тип коннектора, скорость, длину волны и допустимую длину. Затем проверьте состояние линка и уровни приёма, если оборудование их показывает. Не смотрите в торец активного волокна.',
 'Надпись «оптика» не гарантирует совместимость любых двух SFP.',[
 C('Каким сигналом передаются данные в волокне?',['Электрическим током в стекле','Светом','Звуком'],1,'Приёмник преобразует оптический сигнал в электрический для обработки.'),
 M('Что может нарушить оптический линк?',['Грязный разъём','Несовместимые трансиверы','Отсутствие DNS-записи при физическом тесте'],[0,1],'Загрязнение и несовместимость влияют на сам канал; DNS не формирует оптическую связь.'),
 O('Подготовьте оптическое соединение.',['Проверить link и приёмный уровень','Согласовать тип волокна и трансиверы','Подключить чистые совместимые коннекторы'],[1,2,0],'Сначала совместимость, затем монтаж, затем измерение результата.'),
 C('Почему нельзя выбирать SFP только по форме корпуса?',['Важны стандарт, тип волокна и оптические параметры','Все SFP полностью одинаковы','SFP выбирает DNS-сервер'],0,'Одинаковый форм-фактор не означает совместимость оптических характеристик.')])
L(23,'Оптоволокно и коаксиальный кабель',
 'Коаксиальный кабель передаёт электрический сигнал по центральному проводнику с экраном. Оптоволокно передаёт свет и обеспечивает электрическую развязку. Оба типа применяются в своих технологиях доступа и магистралях.',
 'Экран коаксиала уменьшает влияние помех, но не превращает его в диэлектрик. Коаксиальные сети используются, например, в кабельном доступе; скорость и дальность зависят от системы. Оптика не восприимчива к электромагнитным наводкам в самом волокне, но требует оптического оборудования и контроля изгибов.',
 'Между зданиями электрическая развязка и расстояние могут сделать оптику предпочтительной. В существующей кабельной сети провайдера коаксиал может быть частью рабочей инфраструктуры. Сравнивайте полную систему, а не только цену метра кабеля.',
 'Нельзя утверждать, что любой коаксиал всегда медленнее любой оптики: нужны характеристики конкретных технологий.',[
 C('Что находится в центре коаксиального кабеля?',['Проводник','Оптический лазер','Антенна Wi-Fi'],0,'Коаксиал имеет центральный проводник, диэлектрик и экран.'),
 C('Какая среда обеспечивает электрическую развязку самим каналом?',['Оптоволокно','Медный коаксиал','Медная витая пара'],0,'Стеклянное волокно не образует проводящий электрический путь между устройствами.'),
 M('Какие утверждения корректны?',['Коаксиал имеет экран','Волокно чувствительно к чрезмерному изгибу','Любая оптика совместима с любым модемом'],[0,1],'Нужно учитывать конструкцию среды и совместимость оборудования.'),
 C('В кабельной сети доступа уже используется коаксиал. Что оценивать при модернизации?',['Стандарт, оборудование, длину и требования','Только цвет оболочки','Только название среды'],0,'Производительность определяется всей системой передачи.')])
L(24,'Проектируем линию под задачу',
 'Среду и оборудование выбирают совместно: требуемая скорость, расстояние, число портов, питание, резервирование и условия эксплуатации задают ограничения проекта.',
 'Зафиксируйте требования и запас роста. Проверьте пропускную способность uplink, поддержку VLAN и маршрутизации при необходимости, PoE-бюджет и совместимость модулей. Не забывайте доступность электропитания, место установки и возможность обслуживания. Узким местом может оказаться любой участок пути.',
 'Если 20 рабочих мест подключены по 1 Гбит/с, uplink 1 Гбит/с разделяется между ними. Это не всегда проблема: решение зависит от одновременной нагрузки. Для линии 200 м между шкафами обычный медный Ethernet без промежуточных устройств не подходит — выбирают оптику нужного стандарта.',
 'Сумма скоростей портов не равна гарантированной скорости каждого клиента к серверу.',[
 C('Двадцать клиентов делят uplink 1 Гбит/с. Что нужно проверить?',['Одновременную нагрузку uplink','Только число наклеек на портах','Только имя сервера'],0,'Общая пропускная способность выходного канала делится между потоками.'),
 M('Что важно для подключения нескольких PoE-устройств?',['Мощность каждого устройства','Общий PoE-бюджет коммутатора','Только число IPv4-адресов'],[0,1],'Даже при достаточном числе портов суммарной мощности может не хватать.'),
 O('Составьте порядок проектирования.',['Проверить нагрузку и доступность','Определить требования и расстояния','Выбрать совместимые среду и оборудование'],[1,2,0],'Требования определяют выбор, а тесты подтверждают проект.'),
 C('Что делать, если физический линк работает, но пропускная способность недостаточна?',['Измерить загрузку участков и найти узкое место','Сразу менять DNS без проверки','Считать задачу выполненной'],0,'Наличие линка не подтверждает требуемую производительность.')])

# Module 3 — addressing before routing.
L(49,'IPv4: отделяем сеть от узла',
 'IPv4-адрес состоит из 32 бит. Префикс /n задаёт число бит сети; остальные относятся к части узла. Маска определяет границу, а не класс адреса по привычной записи.',
 'Побитовое AND адреса и маски даёт адрес сети. Увеличение длины префикса делит сеть на меньшие блоки. При обычной подсети число доступных адресов узлов равно 2^(32−n)−2: исключены сеть и broadcast. /31 и /32 имеют специальные назначения и не подчиняются этой формуле в обычном виде.',
 '192.168.10.77/26: в последнем октете маска 11000000, то есть 192. Размер блока 64. Адрес 77 находится в блоке 64–127, поэтому сеть — 192.168.10.64. У /26 остаётся 6 бит узла, значит 62 обычных адреса для узлов.',
 'Без маски нельзя надёжно определить, находятся ли два IPv4-узла в одной подсети.',[
 N('Сколько бит содержит IPv4-адрес?','32','IPv4 — 32 бита, обычно записанные четырьмя десятичными октетами.'),
 N('Сколько бит узла остаётся у /26?','6','32−26=6. Всего 64 комбинации, для обычных узлов 62.'),
 C('Как получить адрес сети?',['Выполнить AND адреса и маски','Всегда заменить последний октет на ноль','Сложить IP и порт'],0,'Обнуление последнего октета работает не для всех длин префикса.'),
 N('Сколько обычных адресов узлов в /27?','30','32−27=5 бит; 2^5−2=30.')])
L(50,'Сеть, диапазон и broadcast',
 'Чтобы найти границы подсети, определите маску и размер блока, найдите содержащий адрес блок, затем вычислите broadcast и крайние адреса узлов.',
 'Для /26 маска 255.255.255.192 и шаг 64 в последнем октете: 0, 64, 128, 192. Broadcast — последний адрес блока. Первый обычный узел — сеть+1, последний — broadcast−1. При делении /24 на четыре равные подсети заимствуются два бита: получается /26.',
 '172.16.20.0/26: сеть .0, broadcast .63, диапазон .1–.62, маска 255.255.255.192. Для 192.168.10.77/26 сеть .64, broadcast .127, диапазон .65–.126. Проверяйте, что подсети не пересекаются и полностью покрывают исходный блок.',
 'Адрес сети и broadcast в обычной IPv4-подсети не назначают рабочим станциям.',[
 N('Broadcast для 172.16.20.0/26?','172.16.20.63','Блок занимает адреса .0–.63, последний — broadcast.'),
 N('Новый префикс при делении /24 на четыре равные подсети? Введите число.','26','Для четырёх подсетей нужны два дополнительных бита: 24+2=26.'),
 O('Упорядочьте расчёт диапазона.',['Вычислить первый и последний адрес узла','Определить маску и размер блока','Найти адрес сети и broadcast'],[1,2,0],'Границы узлов выводятся из найденного блока.'),
 N('Первый адрес узла в сети 192.168.10.64/26?','192.168.10.65','Первый узел расположен сразу после адреса сети .64.')])
L(51,'IPv6: больше адресов, другие привычки',
 'IPv6 использует 128-битные адреса, записанные шестнадцатеричными группами. Префикс отделяет сетевую часть. Broadcast отсутствует; для группового обмена используется multicast.',
 'Ведущие нули группы можно опустить; одну непрерывную последовательность нулевых групп разрешено заменить ::. Link-local адреса относятся к локальному каналу, обычно начинаются с fe80::. NDP использует ICMPv6 для обнаружения соседей и маршрутизаторов; ARP для IPv6 не применяется. /64 — обычный размер LAN для SLAAC.',
 '2001:db8:10:0000:0000:0000:0000:0001 сокращается до 2001:db8:10::1. В лаборатории два узла 2001:db8:10::10/64 и ::20/64 связываются в одном сегменте; для удалённой сети требуется IPv6-маршрутизация. Документационный префикс 2001:db8::/32 не предназначен для реального публичного назначения.',
 'Два символа :: нельзя использовать дважды в одном адресе: количество пропущенных групп станет неоднозначным.',[
 N('Сколько бит содержит IPv6-адрес?','128','IPv6 содержит восемь групп по 16 бит.'),
 C('Как IPv6 узнаёт соседей?',['Через NDP/ICMPv6','Через ARP для IPv4','Через IPv4 broadcast'],0,'NDP заменяет функции обнаружения соседей, а IPv6 не использует broadcast.'),
 C('Какая запись синтаксически допустима?',['2001:db8::1','2001::db8::1','2001:zzzz::1'],0,'Двойное сокращение и не шестнадцатеричная группа недопустимы.'),
 C('Почему link-local адрес не подходит для доступа через несколько маршрутизаторов?',['Он имеет область действия одного канала','В нём всегда всего 32 бита','Он является DNS-именем'],0,'Link-local пакеты не пересылаются маршрутизаторами за пределы канала.')])

# Module 4.
L(9,'VLAN: одна коробка, разные сегменты',
 'VLAN разделяет коммутируемую инфраструктуру на логические широковещательные домены. Access-порт обслуживает одну VLAN для конечного узла; trunk передаёт несколько VLAN между сетевыми устройствами.',
 'IEEE 802.1Q помечает кадры VLAN-тегом; native VLAN может передаваться без тега в зависимости от настройки. Создайте VLAN на обоих коммутаторах, назначьте access-порты и разрешите нужные VLAN на trunk. Для связи разных IP-сетей VLAN требуется L3-маршрутизация. STP предотвращает петли L2, блокируя избыточные пути; он не выполняет межвлановую маршрутизацию.',
 'ПК A во VLAN 10 на S1 и ПК B во VLAN 10 на S2 должны связываться через trunk, разрешающий VLAN 10. Если trunk разрешает только 20, кадр VLAN 10 не пройдёт. show vlan brief проверяет принадлежность access-портов, show interfaces trunk — транки и список разрешённых VLAN.',
 'VLAN сама по себе не является правилом firewall: после включения маршрутизации доступ ограничивают ACL или другим контролем.',[
 C('Что переносит несколько VLAN между коммутаторами?',['Trunk','Access-порт одной VLAN','DNS-запись'],0,'Trunk переносит трафик нескольких разрешённых VLAN.'),
 C('На trunk разрешена только VLAN 20. Пройдёт ли кадр VLAN 10?',['Да, всегда','Нет','Только если включить DNS'],1,'Список allowed VLAN фильтрует передаваемые VLAN.'),
 M('Что проверить для узлов одной VLAN на разных коммутаторах?',['VLAN создана на обоих','Нужная VLAN разрешена на trunk','Маршрутизатор обязательно заменяет trunk'],[0,1],'Для одной VLAN нужен исправный L2-путь. Маршрутизация — другая задача.'),
 C('Узлы VLAN 10 и VLAN 20 должны обмениваться IP-пакетами. Что требуется дополнительно?',['Маршрутизатор или L3-коммутатор со шлюзами','Только одинаковые имена ПК','Только broadcast'],0,'Между VLAN нужна L3-функция и корректные шлюзы/правила доступа.')])

# Module 5.
L(2,'OSPF и BGP решают разные задачи',
 'OSPF — протокол внутренней маршрутизации состояния каналов: строит представление топологии и рассчитывает пути по стоимости. BGP обменивается достижимостью префиксов и атрибутами путей, учитывая политики автономных систем.',
 'OSPF обычно используется внутри административного домена, имеет области и соседства. BGP применяется между автономными системами, а iBGP распространяет BGP-маршруты внутри AS. AS_PATH помогает обнаруживать междоменные петли, но выбор BGP-пути не сводится только к минимальному числу AS: влияют политики и атрибуты.',
 'Для трёх маршрутизаторов учебного предприятия подходит OSPF area 0. Для обмена маршрутами организации с двумя провайдерами рассматривают BGP с согласованными фильтрами и политиками. Нельзя просто включить протокол без адресного плана и проверки соседства.',
 'BGP не выбирает всегда географически кратчайший или самый быстрый путь.',[
 C('Какой подход лежит в основе OSPF?',['Состояние каналов и SPF','Только список доменных имён','Трансляция портов'],0,'OSPF распространяет сведения о топологии и вычисляет пути по стоимости.'),
 C('Что особенно важно при выборе маршрутов BGP?',['Политики и атрибуты пути','Только длина кабеля','Номер VLAN клиента'],0,'BGP — протокол маршрутизации, ориентированный на политику.'),
 M('Какие утверждения верны?',['OSPF использует области','BGP может работать внутри AS как iBGP','BGP всегда заменяет DNS'],[0,1],'iBGP переносит BGP-маршруты внутри AS; DNS решает иную задачу.'),
 C('Предприятие обменивается префиксами с независимыми провайдерами. Какой протокол типичен на этой границе?',['BGP','DHCP','ARP'],0,'Между автономными системами обычно используют eBGP.')])
L(52,'Статический маршрут или динамический?',
 'Статический маршрут задаётся администратором. Динамические протоколы обмениваются сведениями и перестраивают маршруты при изменениях. В обоих случаях таблица используется для пересылки пакетов.',
 'Маршрут содержит префикс назначения и следующий узел или выходной интерфейс. При пересылке выбирают наиболее длинный совпадающий префикс. Если источники сообщают один префикс, выбор активного маршрута зависит от административных предпочтений и метрик. Маршрут по умолчанию 0.0.0.0/0 подходит только при отсутствии более специфичного маршрута.',
 'Для 192.168.20.10 совпадают 0.0.0.0/0 и 192.168.20.0/24 — применяется /24. На R1 задают маршрут к LAN R2, а на R2 — обратный к LAN R1. show ip route подтверждает запись, ping next hop — доступность следующего узла.',
 'Наличие маршрута в одну сторону не доказывает двустороннюю связность.',[
 C('Для назначения совпадают /16 и /24. Что выбирается при пересылке?',['/24','/16','Случайный маршрут'],0,'Выигрывает более длинный совпадающий префикс.'),
 N('Введите длину префикса IPv4-маршрута по умолчанию.','0','0.0.0.0/0 совпадает с любым IPv4-адресом, но менее специфичен всех остальных маршрутов.'),
 M('Что проверить после добавления статического маршрута?',['Доступность next hop','Обратный маршрут','Только имя маршрутизатора'],[0,1],'Нужен достижимый следующий узел и путь ответа.'),
 C('Когда динамическая маршрутизация особенно полезна?',['При изменяющейся топологии и резервных путях','Когда нельзя назначать адреса','Только для смены пароля Wi-Fi'],0,'Протоколы могут обнаруживать изменения и рассчитывать новые пути.')])
L(53,'Почему OSPF не видит соседа',
 'OSPF обнаруживает соседей Hello-пакетами, согласует параметры и обменивается описаниями состояния каналов. После синхронизации базы SPF рассчитывает маршруты.',
 'На общем канале проверяют IP-подсеть, area, hello/dead интервалы, тип сети и аутентификацию. Router ID должны быть уникальны. Passive-interface подавляет соседство на интерфейсе. Несовпадение MTU может задержать обмен базой в ExStart/Exchange. Не все соседи в broadcast-сети обязаны быть Full друг с другом: роль DR/BDR влияет на смежность.',
 'R1 и R2 соединены 10.0.0.0/30: адреса .1 и .2. Если R1 использует area 0, а R2 area 1, согласуйте область на канале. Затем проверьте show ip ospf neighbor, show ip route ospf и связность удалённых LAN.',
 'Process ID OSPF локален устройству и не обязан совпадать у соседей; area и согласуемые параметры канала — обязаны.',[
 C('R1 area 0, R2 area 1 на одном канале. Что исправить?',['Согласовать area','Сделать одинаковыми hostname','Удалить все IP-адреса'],0,'Несовпадение area препятствует нормальному соседству на этом канале.'),
 C('Должен ли локальный OSPF process ID всегда совпадать на соседях?',['Да','Нет'],1,'Process ID локален и не является общим номером области.'),
 M('Что проверить при отсутствии соседства?',['Hello/dead интервалы','Passive-interface','Только DNS-суффикс'],[0,1],'Параметры Hello и пассивный режим непосредственно влияют на обнаружение соседей.'),
 C('Соседство застряло в ExStart после замены интерфейса. Что проверить среди прочего?',['MTU','Цвет патч-корда','HTTP cookie'],0,'Несовпадение MTU — одна из причин проблем обмена OSPF-базой, но диагноз нужно подтвердить.')])
L(54,'Соединяем VLAN и проверяем маршрут',
 'Межвлановая маршрутизация выполняется L3-устройством: у каждой VLAN есть IP-интерфейс шлюза. Трафик проходит между сегментами только при корректных L2-путях, адресации и разрешающих правилах.',
 'Router-on-a-stick использует trunk и подинтерфейсы с encapsulation dot1Q. L3-коммутатор может использовать SVI. Сначала проверяют VLAN/access/trunk, затем IP и маску клиента, его шлюз, состояние L3-интерфейса и таблицу маршрутов, затем ACL и обратный путь.',
 'VLAN 10: 192.168.10.0/24, шлюз .1; VLAN 20: 192.168.20.0/24, шлюз .1. Если ПК10 достигает своего шлюза, но не ПК20, проверьте интерфейс VLAN20, маршрутизацию, шлюз ПК20 и правила. Изменяйте одну предполагаемую причину за раз.',
 'Назначение разных IP-подсетей не создаёт VLAN автоматически; VLAN и подсеть — разные понятия.',[
 C('Какая функция нужна для обмена между VLAN?',['L3-маршрутизация','Только MAC flooding','Только Wi-Fi'],0,'Разные VLAN соединяются через маршрутизирующие интерфейсы.'),
 C('Что использует router-on-a-stick?',['Trunk и VLAN-подинтерфейсы','Только один access-порт без тегов для всех VLAN','Только DNS'],0,'Подинтерфейсы различают теги VLAN на общем trunk.'),
 O('Порядок диагностики отсутствующей связи между VLAN.',['Проверить маршруты и ACL','Проверить VLAN и trunk','Проверить IP, маску и шлюз узла'],[1,2,0],'Сначала базовый L2-путь, затем адресация, затем пересылка и ограничения.'),
 C('Клиент VLAN20 имеет шлюз из VLAN10. Какой первый шаг?',['Исправить шлюз на адрес L3-интерфейса VLAN20','Отключить все ACL навсегда','Считать ошибкой только DNS'],0,'Шлюз должен быть достижимым в локальном сегменте клиента.')])

# Module 6 — service mechanism and actual configuration are separate lessons.
L(10,'DHCP: адрес без ручного ввода',
 'DHCP выдаёт клиенту IP-адрес и параметры сети на время аренды. Типичный первоначальный обмен IPv4 — Discover, Offer, Request, Acknowledge (DORA).',
 'Клиент ищет сервер, получает предложение, выбирает его и подтверждает аренду. Помимо адреса важны маска, шлюз и DNS. Broadcast первоначального обмена не маршрутизируется как обычный unicast; для удалённого DHCP-сервера на границе сегмента используется DHCP relay. Продление аренды отличается от первого получения.',
 'ПК подключён к VLAN10 и не имеет адреса. После DORA он получает 192.168.10.21/24, шлюз 192.168.10.1 и DNS 192.168.10.2. Адрес 169.254.x.x в типичной Windows-сети может указывать, что DHCP не был получен, но сам по себе не доказывает конкретную причину.',
 'DHCP не гарантирует доступность Интернета: выданный шлюз или DNS могут быть неверными.',[
 O('Соберите DORA.',['Request','Discover','Acknowledge','Offer'],[1,3,0,2],'Discover → Offer → Request → Acknowledge.'),
 M('Какие параметры может выдать DHCP?',['Шлюз','DNS-сервер','Готовый ответ любого веб-сайта'],[0,1],'DHCP выдаёт параметры подключения, но не выполняет веб-запросы.'),
 C('Сервер в другой подсети. Что переносит DHCP-запросы к нему?',['DHCP relay','Обычный L2 broadcast через все роутеры','NAT всегда автоматически'],0,'Relay обслуживает DHCP-клиентов на удалённом сегменте.'),
 C('Клиент получил IP, но не открывает имена. Что проверить в аренде?',['DNS-параметр','Только MAC принтера','Только имя пользователя'],0,'DHCP мог выдать неправильный DNS даже при правильном IP.')])
L(11,'DNS: от имени к адресу',
 'DNS — распределённая иерархическая система имён. Резолвер получает ответ из кэша или обращается по иерархии к авторитетным серверам; записи A и AAAA связывают имя с IPv4 и IPv6.',
 'Клиент обычно обращается к рекурсивному резолверу. При отсутствии кэша тот может получить указания от корневых и TLD-серверов, затем ответ авторитетного сервера зоны. TTL ограничивает срок кэширования. CNAME задаёт псевдоним, MX — почтовые серверы. DNS использует UDP и TCP, обычно порт 53; возможны защищённые транспортные варианты.',
 'nslookup lab.test 192.168.10.2 проверяет конкретный сервер. Если доступ по IP есть, а по имени нет, сравните настройки клиента, A/AAAA-запись и кэш. Ответ NXDOMAIN означает отсутствие имени по мнению отвечающей системы, а timeout — отсутствие своевременного ответа.',
 'DNS не переносит содержимое сайта и не является маршрутизатором.',[
 C('Какая запись содержит IPv4-адрес?',['A','MX','AAAA'],0,'A — IPv4, AAAA — IPv6, MX — почтовый обмен.'),
 C('Что регулирует TTL DNS-записи?',['Срок кэширования','Число портов коммутатора','Пароль пользователя'],0,'После истечения TTL резолвер должен обновить закэшированные сведения при новом запросе.'),
 O('При пустом кэше упорядочьте упрощённый поиск резолвера.',['Авторитетный сервер зоны','Корневые серверы','Серверы домена верхнего уровня'],[1,2,0],'Корневые серверы направляют к TLD, те — к авторитетным серверам зоны.'),
 C('Сайт доступен по правильному IP, но nslookup возвращает старый адрес. Что проверять?',['Запись DNS и кэш/TTL','Только скорость кабеля','Обязательно заменять все коммутаторы'],0,'Симптом указывает на разрешение имени; причина уточняется запросом к нужному DNS.')])
L(55,'Настраиваем DHCP-пул',
 'DHCP-пул задаёт сеть, маску, диапазон выдачи, шлюз и DNS. Статические адреса инфраструктуры исключают из динамической выдачи; настройки проверяют на реальном клиенте.',
 'Сначала составьте адресный план. Исключите шлюз и серверы, затем создайте пул для правильной подсети. Укажите существующий gateway и доступный DNS. При централизованном сервере настройте relay. После изменения параметров обновите аренду и проверьте binding, а не только сохранённый конфиг.',
 'LAN 192.168.10.0/24: исключены .1–.20; шлюз .1; DNS .2. Первый клиент может получить .21. В Cisco IOS используются ip dhcp excluded-address, ip dhcp pool, network, default-router, dns-server; show ip dhcp binding показывает выданные аренды.',
 'Если исключений нет, динамический адрес может конфликтовать со статическим сервером.',[
 C('Почему адрес шлюза исключают из пула?',['Чтобы не выдать его клиенту повторно','Чтобы удалить маршрут','Чтобы запретить DNS'],0,'Выдача занятого статического адреса создаёт конфликт.'),
 N('Шлюз LAN 192.168.10.0/24 находится на .1. Введите default-router.','192.168.10.1','DHCP должен выдавать адрес действующего маршрутизирующего интерфейса этой LAN.'),
 O('После исправления default-router в пуле:',['Проверить новые параметры и удалённую связность','Обновить аренду клиента','Сохранить исправленную настройку пула'],[2,1,0],'Изменение пула не обязательно мгновенно изменит параметры уже полученной аренды.'),
 C('Клиент получил адрес статического DNS-сервера. Чего не хватило в пуле?',['Исключения или резервирования адреса','Смены SSID','Записи MX'],0,'Адреса инфраструктуры должны быть защищены от случайной динамической выдачи.')])
L(56,'Добавляем запись и проверяем DNS',
 'Настройка DNS включает доступную службу, нужную зону и запись, параметры DNS клиента и проверку ответа. Результат проверяют как по имени, так и по известному IP.',
 'Создайте A-запись для IPv4 или AAAA для IPv6, укажите действующий адрес службы. Проверьте ответ конкретного DNS-сервера и затем системного резолвера клиента. При исправлении учитывайте TTL, локальный кэш и возможную ошибочную AAAA-запись, если приложение предпочитает IPv6.',
 'В лаборатории lab.test → 192.168.10.2. На клиенте DNS=192.168.10.2. Выполните nslookup lab.test 192.168.10.2, затем откройте сервис. Если имя разрешается правильно, но HTTP выключен, править A-запись бесполезно: диагностируйте приложение.',
 'Успешное разрешение имени не доказывает работу службы на полученном адресе.',[
 C('Для lab.test нужен IPv4-адрес 192.168.10.2. Какую запись добавить?',['A','MX','PTR обязательно вместо A'],0,'A сопоставляет имя IPv4-адресу.'),
 N('Введите значение A-записи lab.test для сервера 192.168.10.2.','192.168.10.2','В A-записи хранится IPv4-адрес, а не URL с https://.'),
 M('Что сравнить при ошибке разрешения имени?',['Ответ конкретного DNS','Настройки DNS на клиенте','Только название сетевой карты'],[0,1],'Так различают проблему данных на сервере и выбора резолвера клиентом.'),
 C('DNS вернул правильный адрес, ping работает, HTTP-сервис остановлен. Что исправить?',['Запустить и проверить HTTP-службу','Поменять правильную A-запись','Удалить маску сети'],0,'Проблема на прикладном уровне, а не в разрешении имени.')])

# Module 7.
L(8,'NAT и PAT: что меняется в пакете',
 'NAT преобразует IP-адреса на границе сетей. PAT дополнительно различает потоки по транспортным портам и позволяет многим внутренним узлам использовать один внешний адрес.',
 'Статический NAT может сопоставлять адрес один-к-одному; динамический NAT берёт адрес из пула. PAT ведёт таблицу соответствий внутренних и внешних конечных точек. Ответный пакет по записи таблицы направляется нужному узлу. NAT не заменяет firewall и не гарантирует разрешённый доступ.',
 '192.168.10.10:51000 и 192.168.10.11:51000 обращаются к одному серверу TCP 443. PAT может представить их как 203.0.113.5:40001 и :40002. Один внешний IP сохранён, но внешние порты отличаются, поэтому ответы можно различить.',
 'При PAT нельзя безусловно сохранять одинаковый внешний порт для двух одинаково адресованных внешних потоков.',[
 C('Что позволяет различить клиентов при общем внешнем IP?',['Трансляции транспортных портов','Только одинаковый hostname','Только broadcast'],0,'PAT использует порты и состояние соответствующих потоков.'),
 C('Является ли NAT заменой политики firewall?',['Нет','Да, всегда'],0,'Трансляция адресов и разрешение доступа — разные задачи.'),
 M('Какие данные полезны в таблице NAT/PAT?',['Внутренний адрес и порт','Внешний преобразованный адрес и порт','Цвет стойки'],[0,1],'Таблица сопоставляет конечные точки для прямого и обратного трафика.'),
 C('Два клиента используют один внешний адрес. Как назвать типичную трансляцию с различными портами?',['PAT','Только статический NAT 1:1','OSPF'],0,'PAT позволяет разделять один внешний адрес между потоками.')])
L(57,'Выпускаем LAN во внешнюю сеть',
 'Для NAT/PAT нужны корректные внутренний и внешний интерфейсы, правило трансляции, маршруты и доступный внешний ресурс. Проверка выполняется после генерации трафика.',
 'В типичной конфигурации Cisco интерфейсы отмечают ip nat inside/outside. ACL выбирает адреса для трансляции; overload включает PAT. Эта ACL выбора адресов не равна интерфейсной ACL фильтрации. Убедитесь в маршруте по умолчанию и обратной достижимости внешнего адреса. Пустая динамическая таблица до обращения клиента нормальна.',
 'Для 192.168.10.0/24 создайте ACL выбора этой сети и ip nat inside source list 1 interface g0/1 overload, если g0/1 действительно внешний. Откройте внешний учебный ресурс с двух клиентов и изучите show ip nat translations и counters.',
 'Правильное правило NAT не исправит отсутствующий маршрут по умолчанию.',[
 C('Зачем в типичном IOS PAT используется overload?',['Для разделения внешнего адреса с помощью портов','Для отключения маршрутов','Для шифрования DNS'],0,'Overload включает трансляцию многих потоков через доступный внешний адрес.'),
 O('Порядок проверки динамической трансляции.',['Посмотреть таблицу трансляций','Проверить интерфейсы и маршруты','Сгенерировать трафик клиента'],[1,2,0],'Таблица появляется при реальном обмене после правильной базовой настройки.'),
 C('До первого запроса таблица PAT пуста. Это обязательно ошибка?',['Нет','Да'],0,'Динамические записи создаются по мере появления трафика.'),
 C('Inside/outside и PAT верны, но маршрута наружу нет. Что сделать?',['Настроить достижимый внешний маршрут','Сменить MAC всех клиентов','Считать NAT достаточным'],0,'Трансляция не выбирает отсутствующий сетевой путь.')])

# Module 8.
L(4,'Wi-Fi и Bluetooth: разделяем радиосреду',
 'Wi-Fi обеспечивает беспроводное подключение к локальной сети, обычно через точку доступа. Bluetooth рассчитан на взаимодействие близких устройств и периферии; сценарии и энергопотребление зависят от режима.',
 'Устройства используют общую радиосреду, поэтому помехи, расстояние, препятствия и число активных клиентов влияют на качество. Wi-Fi-клиент выбирает сеть, согласует безопасность, ассоциируется и получает IP-параметры. У Bluetooth применяются обнаружение, сопряжение и профили служб; совместимость профиля важна не меньше наличия радио.',
 'Ноутбук подключают к SSID LabNet для доступа к LAN, гарнитуру — через Bluetooth-профиль аудио. При плохой скорости Wi-Fi проверяют уровень сигнала, загрузку канала и помехи. Наличие SSID в списке не доказывает успешную аутентификацию и получение IP.',
 'Wi-Fi не равен Интернету, а Bluetooth не является универсальной заменой офисной LAN.',[
 C('Какой тип подключения типичен для беспроводной гарнитуры?',['Bluetooth с подходящим профилем','OSPF area 0','Оптический транк'],0,'Bluetooth поддерживает профили взаимодействия периферии, включая аудио.'),
 M('Что влияет на Wi-Fi-соединение?',['Помехи и препятствия','Число активных клиентов','Только имя браузера'],[0,1],'Радиосреда разделяется и зависит от условий распространения.'),
 O('Типичная последовательность подключения Wi-Fi-клиента.',['Получить IP-параметры','Выбрать SSID','Пройти согласование безопасности и подключение'],[1,2,0],'IP-конфигурация обычно происходит после установления канального подключения.'),
 C('SSID виден, но ключ неверен. Достаточно ли видимости сети для обмена данными?',['Нет, нужно успешное подключение','Да, любой видимый SSID даёт доступ'],0,'Обнаружение сети и аутентификация — разные этапы.')])
L(41,'WPA2 и WPA3: выбираем защиту',
 'WPA2 и WPA3 защищают беспроводной доступ. WPA2-Personal обычно использует общий ключ и AES-CCMP; WPA3-Personal использует SAE и усиливает защиту аутентификации, но требует поддержки устройств.',
 'Для рабочего подключения должны совпадать SSID, поддерживаемый режим безопасности и корректные учётные данные. Enterprise-режимы используют индивидуальную аутентификацию, например через 802.1X. Переходный режим может сохранять совместимость со старыми клиентами, но его свойства нельзя считать тождественными чистому WPA3.',
 'В лаборатории включите WPA2-AES либо WPA3-SAE на совместимых устройствах. Проверьте верный и неверный ключ. Разделите гостевой и служебный доступ. Если WPA3-клиент не подключается, проверьте поддержку режима и настройки, а не отключайте защиту.',
 'WPA3 не заменяет обновления, надёжные учётные данные, защиту конечного устройства и сегментацию.',[
 C('Что используется в WPA3-Personal для аутентификации?',['SAE','Открытая сеть без проверки','NAT'],0,'SAE — ключевое отличие WPA3-Personal от WPA2-Personal.'),
 C('Старый клиент не поддерживает выбранный WPA3-режим. Что проверить?',['Совместимость и допустимый режим перехода','Только DNS-зону','Отключить любое шифрование навсегда'],0,'Решение учитывает совместимость и политику безопасности, а не просто убирает защиту.'),
 M('Какие проверки нужны после настройки?',['Успешный вход с верными данными','Отказ с неверными данными','Публикация рабочего ключа в отчёте'],[0,1],'Проверяются положительный и отрицательный сценарии без раскрытия секрета.'),
 C('Какое утверждение о WPA3 верно?',['Улучшает защиту, но не устраняет все сетевые угрозы','Отменяет необходимость обновлений','Всегда работает на любом старом клиенте'],0,'Защита радиодоступа — один из уровней общей безопасности.')])

# Module 9.
L(14,'Windows Server и Linux в сети',
 'Серверные ОС предоставляют сетевые службы и средства управления: пользователи, права, файлы, DNS/DHCP, веб-приложения, журналирование и обновления. Выбор определяется требованиями и компетенциями команды.',
 'Windows Server часто используется с Active Directory и групповыми политиками. Linux широко применяется для сетевых и прикладных служб, автоматизации и контейнерных сред. Обе системы требуют настройки прав, службы времени, резервирования и обновлений. Установленная роль не означает, что служба запущена и доступна через firewall.',
 'На Linux состояние службы проверяют systemctl status, слушающие сокеты — ss -lnt; на Windows — состояние службы и доступность нужного порта. Если узел отвечает на ping, но файловая служба не работает, проверяют службу, разрешения и фильтрацию.',
 'Серверная ОС не делает все ресурсы доступными автоматически: каждый сервис имеет свою конфигурацию и права.',[
 C('Какая задача типична для серверной ОС?',['Централизованные учётные записи и сетевые службы','Только отображение обоев','Замена всех физических кабелей'],0,'Серверные ОС организуют ресурсы и управление доступом.'),
 C('Что показывает ss -lnt в Linux?',['Слушающие TCP-сокеты в числовом виде','Список VLAN на любом коммутаторе','Содержимое всех DNS-зон'],0,'Команда помогает проверить, слушает ли служба TCP-порт.'),
 M('Что проверить, если ping есть, а служба недоступна?',['Состояние службы','Firewall и права доступа','Только тип мыши'],[0,1],'Сетевая достижимость не доказывает прикладную доступность.'),
 C('Как выбирать между Windows Server и Linux?',['По требованиям служб, интеграции и поддержке команды','По обещанию, что одна ОС не требует обновлений','Только по длине названия'],0,'Обе платформы требуют эксплуатации и защиты; выбор должен быть обоснован.')])
L(15,'Сетевой принтер и общая периферия',
 'Сетевые периферийные устройства предоставляют общую функцию через сеть: печать, сканирование или хранение. Для их использования нужны связность, корректная служба, клиентская настройка и права.',
 'Назначьте устройству устойчивый адрес: статический вне DHCP-пула или резервирование. Установите совместимый драйвер и настройте очередь либо службу доступа. Ограничьте административный интерфейс, измените заводские учётные данные и обновляйте устройство. Отдельно проверяйте сетевой путь и само выполнение операции.',
 'Принтер 192.168.10.30 доступен по IP, но документ стоит в очереди. Проверьте очередь, драйвер, выбранный протокол, бумагу и ошибки устройства. Не меняйте адрес наугад. В отчёте полезна тестовая страница и запись о правах доступа.',
 'Сетевой принтер тоже является узлом с настройками и рисками; его административная панель не должна быть открыта всем.',[
 C('Как избежать случайной смены адреса принтера?',['Статический адрес вне пула или резервирование DHCP','Одинаковый адрес со шлюзом','Перезапуск DNS каждый час'],0,'Устойчивый адрес позволяет клиентам и очередям находить устройство.'),
 M('Ping принтера проходит, печати нет. Что проверить?',['Очередь и драйвер','Ошибки самого принтера','Только маршрут к публичному сайту'],[0,1],'Проверяется прикладная цепочка печати, а не только ICMP.'),
 O('Подключение сетевого принтера.',['Выполнить тестовую печать','Назначить устойчивый адрес','Настроить клиентскую очередь и драйвер'],[1,2,0],'После адресации и клиентской настройки проверяют реальную операцию.'),
 C('Как ограничить доступ к управлению принтером?',['Разрешить его только нужным администраторам','Дать всем общую администраторскую запись','Удалить все журналы'],0,'Управление периферией также подчиняется принципу минимальных прав.')])
L(16,'Виртуальные серверы, реальные ресурсы',
 'Виртуализация позволяет нескольким изолированным виртуальным машинам использовать один физический сервер под управлением гипервизора. Это упрощает консолидацию, перенос и управление ресурсами.',
 'Каждая ВМ получает виртуальные CPU, память, диски и сетевые интерфейсы. Виртуальный switch соединяет ВМ и uplink с физической сетью; VLAN и политики остаются значимыми. Планируют общую нагрузку, отказ физического хоста и резервное копирование. Snapshot удобен для краткосрочного отката, но не заменяет независимую резервную копию.',
 'На хосте 16 ГБ RAM оставьте 4 ГБ для гипервизора и инфраструктуры. Две ВМ по 6 ГБ помещаются в оставшиеся 12 ГБ; две по 8 ГБ — нет в модели без overcommit. Также проверьте дисковые IOPS и пропускную способность uplink.',
 'Виртуальная машина не становится физически независимой от хоста и его питания.',[
 C('Кто распределяет физические ресурсы между ВМ?',['Гипервизор','DNS-кэш','Пассивный патч-панель'],0,'Гипервизор управляет выполнением и ресурсами виртуальных машин.'),
 N('16 ГБ всего, 4 ГБ зарезервировано. Сколько ГБ остаётся ВМ без overcommit?','12','16−4=12 ГБ доступно для распределения в этой модели.'),
 M('Какие риски нужно учитывать?',['Отказ общего хоста','Нехватка памяти или IOPS','Полное отсутствие необходимости бэкапов'],[0,1],'Консолидация создаёт общие зависимости, а резервирование остаётся необходимым.'),
 C('Является ли snapshot на том же хранилище полной заменой резервной копии?',['Нет','Да'],0,'Отказ хранилища может уничтожить и ВМ, и её snapshot.')])
L(18,'Внедряем изменения без сюрпризов',
 'Интеграция новой сетевой технологии начинается с инвентаризации и требований, затем проходит через проверку совместимости, пилот, план отката, поэтапное внедрение и контроль результата.',
 'Проверьте адресные пространства, протоколы, версии ПО, производительность и политики. Зафиксируйте зависимости: DNS, время, маршруты, идентификация и мониторинг. Определите окно изменений и критерии успеха/отката. Резервные копии конфигурации и доступ к консоли должны быть готовы до изменения.',
 'При добавлении новой VLAN сначала создайте её на ограниченном участке, настройте trunk и шлюз, проверьте тестовый клиент и правила доступа. Затем распространяйте конфигурацию. Если возникает сбой, сравните с исходным состоянием и примените запланированный откат.',
 'Одновременная смена адресации, firewall и DNS без контрольных точек затрудняет поиск причины.',[
 O('Выберите последовательность внедрения.',['Масштабирование после проверки','Инвентаризация и требования','Пилот с планом отката'],[1,2,0],'Сначала понять среду, затем испытать изменение, затем расширять.'),
 M('Что нужно подготовить до изменения?',['Копию конфигурации','Критерии отката','Удаление всех журналов'],[0,1],'Резервная конфигурация и критерии позволяют восстановиться обоснованно.'),
 C('Пилот нарушил доступ к службе. Как действовать?',['Сопоставить симптомы с критериями и при необходимости откатить','Продолжить массовое внедрение без проверки','Игнорировать пользователей'],0,'Пилот нужен именно для обнаружения проблем до широкого внедрения.'),
 C('Почему изменения вводят поэтапно?',['Чтобы локализовать последствия и проверить каждую гипотезу','Чтобы никогда не тестировать результат','Чтобы избежать документации'],0,'Контролируемые этапы уменьшают неопределённость диагностики.')])

# Module 10.
L(26,'ping, tracert и netstat: разные вопросы',
 'ping проверяет ICMP-ответ и задержку, tracert/traceroute исследует путь по ответам на истечение TTL, netstat показывает соединения и сокеты. Эти команды дают наблюдения, а не готовый диагноз.',
 'Начните с локального интерфейса и адреса, затем шлюза, удалённого IP и имени. Отсутствие ping-ответа может быть вызвано фильтрацией ICMP, а не только выключенным узлом. Промежуточный узел traceroute может не отвечать, продолжая пересылать трафик. Слушающий порт подтверждает наличие сокета, но не полную работоспособность приложения.',
 'ping 192.168.10.2 успешен, nslookup lab.test возвращает неверный IP. Исправляйте DNS, а не физическую линию. Если DNS правильный, но веб-порт закрыт, проверьте службу и firewall. Сохраните вывод команд до и после изменения.',
 'Одна звёздочка в tracert не доказывает обрыв именно на этом маршрутизаторе.',[
 C('Какая команда помогает увидеть слушающие сокеты?',['netstat','Только ping','Только hostname'],0,'netstat показывает соединения/сокеты в зависимости от параметров.'),
 C('Узел не отвечает на ping. Единственная ли причина — выключенное питание?',['Нет, возможна фильтрация ICMP','Да'],0,'Нужно проверять другие сигналы и доступность службы.'),
 O('Упорядочьте базовую диагностику.',['Проверить имя и прикладную службу','Проверить интерфейс и IP клиента','Проверить шлюз и удалённый IP'],[1,2,0],'Идём от локальных предпосылок к удалённому приложению.'),
 C('tracert показывает * на одном узле, но последующие узлы отвечают. Что это значит?',['Узел мог не ответить на probe, но пересылка продолжается','Путь обязательно оборван','DNS всегда сломан'],0,'Ответы маршрутизатора на диагностические запросы и транзитная пересылка — разные процессы.')])
L(29,'Мониторинг: знать норму, видеть отклонение',
 'Мониторинг отслеживает доступность, задержки, потери, загрузку каналов, ошибки интерфейсов и состояние служб. Он сравнивает наблюдения с нормой и уведомляет о значимых отклонениях.',
 'Выберите объект, метод, интервал и порог. Определите получателя уведомления и процедуру реакции. Метрики собираются, например, SNMP, агентами или активными проверками. Кратковременный всплеск не всегда авария; полезны несколько последовательных неудач, зависимости и контроль восстановления.',
 'Проверяйте HTTPS каждые 30 секунд и поднимайте тревогу после трёх неудач подряд. Если ping есть, а HTTP возвращает ошибку, сигнал о службе точнее ICMP-проверки. При плановом обслуживании отметьте окно, чтобы не принять ожидаемое отключение за новый инцидент.',
 'Зелёный ping не заменяет мониторинг бизнес-функции приложения.',[
 C('Зачем нужен исходный нормальный уровень метрик?',['Чтобы отличать отклонение от обычного поведения','Чтобы запретить любые изменения','Чтобы не собирать данные'],0,'Без baseline трудно интерпретировать значение метрики.'),
 N('Проверка каждые 30 секунд, порог 3 последовательных провала. Каково окно трёх интервалов в секундах?','90','В учебной модели 3×30=90 секунд; фактическая задержка обнаружения зависит от момента сбоя и timeout.'),
 M('Что должен включать рабочий мониторинг?',['Получателя уведомления','Проверку восстановления','Только красивый график без реакции'],[0,1],'Наблюдение полезно, когда приводит к действию и подтверждению восстановления.'),
 C('Нужно обнаружить сбой веб-приложения при исправном ICMP. Что добавить?',['Проверку HTTP/HTTPS-функции','Только второй ping','Только проверку имени файла бэкапа'],0,'Прикладная проверка обнаруживает отказ службы, скрытый от простого ICMP.')])
L(30,'Читаем журнал как временную шкалу',
 'Журналирование фиксирует события: время, источник, пользователя, действие и результат. Сопоставление журналов помогает искать причины сбоев и расследовать инциденты.',
 'Синхронизируйте время и часовые пояса, сохраняйте логи централизованно и ограничивайте изменение/удаление. Разделяйте факт и гипотезу: запись failed login подтверждает неудачный вход, но сама по себе не доказывает атаку. Корреляция событий и контекст изменений повышают достоверность вывода.',
 '10:02 — пять failed login; 10:03 — success с того же источника; 10:04 — configuration changed; 10:05 — link down. Последовательность подозрительна, но может быть работой администратора. Сверьте заявку на изменение, учётную запись, источник и конфигурационный diff.',
 'Близость событий по времени не доказывает причинную связь без дополнительных данных.',[
 C('Что является наблюдаемым фактом?',['В журнале пять неудачных входов','Злоумышленник точно украл все файлы','Любой сбой вызван DNS'],0,'Первая формулировка непосредственно следует из записи; остальные требуют доказательств.'),
 M('Что помогает сопоставлять логи разных устройств?',['Синхронизированное время','Понимание часовых поясов','Случайная смена часов'],[0,1],'Согласованное время необходимо для корректной временной шкалы.'),
 O('Как расследовать подозрительную последовательность?',['Сформулировать подтверждённый вывод','Собрать записи и сохранить их','Сопоставить источники и контекст изменений'],[1,2,0],'Вывод следует из сохранённых доказательств и сопоставления, а не предшествует им.'),
 C('После failed login произошёл успешный вход. Что делать?',['Проверить контекст и полномочия, собрать подтверждения','Автоматически считать любого пользователя преступником','Удалить записи'],0,'Сигнал требует проверки, а журнал должен быть сохранён.')])
L(59,'Wireshark: читаем пакет, а не угадываем',
 'Wireshark захватывает и декодирует сетевые пакеты. Он показывает время, протоколы, MAC/IP-адреса, порты, флаги и доступную полезную нагрузку; возможности зависят от точки захвата и шифрования.',
 'Выберите интерфейс, выполните контролируемый обмен и остановите захват. Display filter скрывает неподходящие пакеты из представления, но не удаляет их из файла. Для ICMP используйте icmp, для DNS — dns, для TCP-порта 443 — tcp.port == 443. Захватывайте только разрешённый лабораторный трафик.',
 'У ICMP echo request и reply сопоставьте адреса, identifier и sequence. У обычного DNS свяжите query/response по transaction ID, имени и конечным точкам. Клиентский порт обычно динамический, серверный — 53. HTTPS-пакеты не раскрывают текст страницы без необходимых ключей и условий расшифровки.',
 'Фильтр отображения — не то же самое, что фильтр захвата; шифрование не исчезает от открытия pcap.',[
 N('Введите display filter для ICMP.','icmp','Фильтр icmp показывает декодированные ICMP-пакеты.'),
 C('Как связать DNS-запрос и ответ?',['По ID, имени и конечным точкам','Только по цвету строки','По номеру порта коммутатора'],0,'Совместно учитываются идентификатор обмена и контекст пакетов.'),
 M('Что можно увидеть в типичном захвате HTTPS без расшифровки?',['IP-адреса','TCP-порты при HTTPS поверх TCP','Всегда весь пароль и страницу открытым текстом'],[0,1],'Сетевые метаданные доступны, а прикладная полезная нагрузка защищена TLS.'),
 C('После display filter пакет не виден. Удалён ли он из исходного pcap?',['Нет, изменилось представление','Да, безвозвратно'],0,'Фильтр отображения не удаляет записи из сохранённого захвата.')])

# Module 11.
L(7,'Политика безопасности начинается с доступа',
 'Сетевая политика безопасности определяет допустимые действия, доступы и ответственность. Она связывает рабочие требования с техническими мерами: сегментацией, аутентификацией, фильтрацией, обновлениями и аудитом.',
 'Составьте матрицу «кто → куда → какой сервис → зачем». Применяйте минимальные права, разделяйте административные и пользовательские подключения. Укажите владельца правила, срок пересмотра и порядок исключений. Проверяйте разрешённые и запрещённые сценарии, а не только факт наличия firewall.',
 'Сотрудникам разрешён HTTPS к приложению, администраторам — SSH из выделенной подсети, гостям — только нужный внешний доступ. Эти требования затем переводятся в группы, ACL и правила firewall. Изменение должно сопровождаться тестами и записью в журнале.',
 'Правило «разрешить всем всё» может устранить симптом, но не выполнить политику безопасности.',[
 C('С чего начать набор правил доступа?',['С матрицы рабочих требований','С разрешения любого трафика навсегда','Со случайного списка портов'],0,'Сначала определяют необходимость доступа, затем реализуют ограничения.'),
 M('Какие меры дополняют сетевую фильтрацию?',['Обновления','Аутентификация и аудит','Общий пароль администратора для всех'],[0,1],'Защита строится несколькими согласованными слоями.'),
 C('Что означает минимальный доступ?',['Только необходимые ресурсы и действия','Запрет любой работы','Всегда полный доступ после входа'],0,'Права должны соответствовать задаче и роли пользователя.'),
 C('Гость должен выходить в Интернет, но не управлять сервером. Какой принцип реализуется?',['Разграничение доступа по назначению','Обязательная маршрутизация без ограничений','Отмена политик'],0,'Связность должна соответствовать разрешённым сценариям.')])
L(25,'Правила эксплуатации тоже нужны',
 'Политики управления инфраструктурой определяют, кто изменяет сеть, как согласуются изменения, где хранятся конфигурации и как подтверждается результат. Это делает обслуживание воспроизводимым и контролируемым.',
 'Ведите инвентаризацию устройств, адресов, владельцев и зависимостей. Используйте индивидуальные учётные записи, роли, резервные копии конфигураций и журнал изменений. Для каждой правки нужны цель, риск, окно, проверка и план отката. Регулярно пересматривайте устаревшие правила.',
 'Изменение ACL оформляют с перечнем разрешённых потоков, исходным конфигом и тестами. После внедрения сохраняют diff, результат проверок и ответственного. Если правило временное, указывают дату удаления, чтобы исключение не стало постоянным.',
 'Отсутствие документации делает сеть зависимой от памяти одного администратора.',[
 M('Что должно сопровождать изменение?',['План отката','Критерии успешности','Удаление истории конфигурации'],[0,1],'Контролируемое изменение предусматривает проверку и восстановление.'),
 C('Почему индивидуальные учётные записи лучше общей административной?',['Позволяют связать действия с ответственным','Полностью исключают все угрозы','Не требуют паролей'],0,'Персональные записи улучшают контроль и аудит, но не заменяют остальные меры.'),
 O('Жизненный цикл временного правила.',['Пересмотреть и удалить по сроку','Согласовать цель и срок','Внедрить и проверить'],[1,2,0],'Исключения должны иметь управляемое окончание.'),
 C('После смены администратора неизвестно назначение ACL. Чего не хватает?',['Документации владельца, цели и истории изменения','Нового цвета интерфейса','Ещё одного общего пароля'],0,'Правило должно быть объяснимо независимо от автора.')])
L(27,'Угроза и DDoS: почему падает доступность',
 'Сетевая угроза — потенциальное нарушение конфиденциальности, целостности или доступности. DDoS пытается исчерпать ресурс распределённым потоком запросов или пакетов.',
 'Перегружаться могут канал, таблицы состояния, процессор или приложение. Симптом высокой нагрузки сам по себе не доказывает атаку: бывает законный всплеск. Сравните источники, характер запросов, длительность и обычный уровень. Защита может требовать фильтрации у провайдера, CDN/очистки, лимитов и устойчивой архитектуры.',
 'Если входящий канал заполнен до вашего firewall, локальное правило не вернёт уже потерянную полосу. Нужна помощь выше по сети. В учебном анализе используйте готовые метрики или ограниченные синтетические события; реальную нагрузочную атаку не запускайте.',
 'Один локальный firewall не гарантирует защиту от любой по масштабу DDoS-атаки.',[
 C('Какое свойство чаще всего нарушает DDoS?',['Доступность','Только цвет интерфейса','Обязательно только конфиденциальность'],0,'Основная цель — сделать ресурс недоступным или деградировать обслуживание.'),
 C('Канал до организации уже насыщен. Где нужна помощь?',['У провайдера или сервиса фильтрации выше по пути','Только в настройках принтера','Только в локальном DNS-кэше'],0,'Фильтрация после насыщенного канала не возвращает его ёмкость.'),
 M('Что поможет отличить атаку от обычного пика?',['Структура источников и запросов','Сравнение с нормальным уровнем','Только одно большое число без контекста'],[0,1],'Нужен контекст нескольких наблюдений.'),
 C('Высокий трафик обнаружен впервые. Как сформулировать вывод?',['Есть аномалия, нужна проверка причин','Атака доказана одним графиком','Можно игнорировать доступность'],0,'Наблюдение и подтверждённый диагноз следует разделять.')])
L(28,'Физическая безопасность сети',
 'Физическая защита предотвращает несанкционированный доступ к оборудованию и снижает риски отказа питания, перегрева, повреждения кабелей и среды. Она дополняет логическую защиту.',
 'Используйте контролируемый доступ к стойкам, учёт посетителей, аккуратную маркировку, защиту кабельных трасс, охлаждение и ИБП. Проверяйте автономность и состояние батарей, а не только наличие устройства. План аварийного отключения и резервирование питания учитывают зависимости оборудования.',
 'Даже правильно настроенный firewall не поможет, если посторонний получил доступ к консоли или отключил питание единственного коммутатора. Для серверной определите допущенные роли, порядок работ и реакцию на температуру или пропадание питания.',
 'ИБП даёт ограниченное время работы и не является бесконечным источником энергии.',[
 M('Какие меры относятся к физической защите?',['Контроль доступа к стойке','Охлаждение и ИБП','Только смена DNS-записи'],[0,1],'Эти меры защищают оборудование и условия его работы.'),
 C('Почему нужно тестировать ИБП?',['Батарея и фактическая нагрузка определяют автономность','Само наличие гарантирует вечную работу','Чтобы удалить логи'],0,'Реальное время работы зависит от состояния батареи и нагрузки.'),
 C('Посторонний получил доступ к консоли маршрутизатора. Что нарушено?',['Физический контроль доступа','Только формат IP','Только имя SSID'],0,'Доступ к оборудованию может обойти часть сетевых ограничений.'),
 C('Какой подход лучше для кабельного хозяйства?',['Маркировка, защищённые трассы и контролируемые работы','Неизвестные кабели и свободный доступ всем','Хранение рабочих паролей на стойке'],0,'Организация физической среды снижает случайные и намеренные нарушения.')])
L(34,'DDoS и Man-in-the-Middle',
 'DDoS воздействует прежде всего на доступность ресурсов. Man-in-the-Middle означает вмешательство посредника в обмен с риском чтения или изменения данных. Защита этих сценариев требует разных мер.',
 'Для DDoS применяют контроль нагрузки, фильтрацию и поддержку вышестоящей сети. Для защиты от подмены посредником важны TLS с проверкой имени и цепочки сертификата, безопасная аутентификация и защищённая локальная среда. Сам факт шифрования без проверки стороны не решает проблему подмены.',
 'Браузер сообщает о неверном имени сертификата. Не обходите проверку ради доступа: проверьте адрес, время, цепочку доверия и настройки сервера. Если же сервис недоступен из-за насыщенного канала, исправление сертификата не устранит перегрузку.',
 'Похожие симптомы «сайт не работает» могут иметь разные причины, поэтому меры выбирают после диагностики.',[
 C('Какой механизм непосредственно помогает против подмены сервера?',['Проверка TLS-сертификата и имени','Отключение проверки сертификатов','Только увеличение скорости мыши'],0,'Клиент должен удостовериться, с какой стороной устанавливает защищённое соединение.'),
 C('Распределённый поток исчерпывает канал. Какой сценарий вероятнее?',['DDoS','Только обычная смена DNS TTL','Обязательно ошибка принтера'],0,'Перегрузка распределённым потоком согласуется с DDoS, но требует подтверждения.'),
 M('Что проверять при ошибке TLS?',['Имя сервера','Время и цепочку доверия','Нужно ли навсегда отключить проверки'],[0,1],'Исправляют причину ошибки доверия, не отменяя защиту.'),
 C('Почему шифрование без аутентификации сервера недостаточно?',['Можно зашифровать обмен с подменённой стороной','Шифрование всегда устраняет любую подмену','DNS больше не нужен'],0,'Нужно не только скрыть данные, но и проверить получателя.')])
L(37,'Firewall: пакет проходит по правилу',
 'Брандмауэр фильтрует трафик по политике. Правила могут учитывать адреса, протоколы, порты и состояние соединения. Stateful firewall отслеживает контекст обмена, а не только отдельный пакет.',
 'Сначала определите разрешённые потоки, затем порядок правил и поведение по умолчанию. Ограничьте административный доступ, учитывайте ответный трафик и журналирование отказов. Правила проверяйте с разных источников. До изменения удалённого доступа обеспечьте путь отката или консоль.',
 'Клиентам разрешён TCP 443 к веб-серверу, SSH TCP 22 — только подсети администратора, остальные новые соединения запрещены. Для stateful firewall ответы established разрешаются в соответствии с политикой. Проверка должна показать и успешный HTTPS, и отказ обычному клиенту в SSH.',
 'Нельзя проверять правило только одним разрешённым запросом: запрещённые сценарии тоже обязательны.',[
 C('Что означает stateful?',['Учитывает состояние соединения','Учитывает только цвет кабеля','Не имеет правил'],0,'Состояние позволяет связывать пакет с ранее разрешённым соединением.'),
 M('Какие тесты нужны после изменения?',['Разрешённый поток проходит','Запрещённый поток блокируется','Все порты открыты без проверки'],[0,1],'Положительные и отрицательные проверки подтверждают политику.'),
 C('Как безопаснее менять удалённый административный доступ?',['Иметь консоль или план отката','Сначала навсегда заблокировать все пути','Удалить резервную конфигурацию'],0,'Ошибка правила не должна лишить возможности восстановить доступ.'),
 C('Обычному пользователю разрешён HTTPS, но запрещён SSH. Какой результат ожидается?',['443 проходит, 22 блокируется','Любой порт проходит','443 всегда блокируется вместе с 22'],0,'Правило должно различать назначение сервисов.')])
L(38,'IDS: сигнал требует проверки',
 'IDS обнаруживает подозрительную активность и уведомляет администратора. IPS может блокировать трафик на пути. Обнаружение строится на сигнатурах, аномалиях и контексте.',
 'Сигнатура ищет известный шаблон, а анализ аномалий — отклонение от нормы. Возможны ложные положительные и пропущенные события. Срабатывание проверяют по источнику, времени, активу и связанным логам. Для IPS учитывают риск ошибочной блокировки рабочих процессов.',
 '1000 SYN к 100 портам одного узла похоже на сканирование; серия failed login — на подбор, но может быть ошибкой автоматизации. Плановая резервная копия тоже создаёт большой поток. Назначайте приоритет с учётом ценности узла и подтверждений.',
 'Срабатывание IDS — основание для расследования, а не окончательное доказательство компрометации.',[
 C('Чем IPS отличается от пассивной IDS?',['Может блокировать на пути трафика','Не видит события','Всегда заменяет резервные копии'],0,'IPS способен вмешиваться в поток, поэтому ложные срабатывания особенно важны.'),
 C('Плановый бэкап вызвал тревогу объёма. Что проверить?',['Расписание и контекст, затем уточнить правило','Сразу удалить все копии','Игнорировать все будущие тревоги'],0,'Нужна настройка по контексту без полной потери наблюдаемости.'),
 M('Что полезно при расследовании IDS-события?',['Источник и целевой актив','Связанные логи и время','Только цвет индикатора'],[0,1],'Сопоставление нескольких источников помогает подтвердить или опровергнуть гипотезу.'),
 C('Что такое false positive?',['Тревога о нормальной активности','Любая подтверждённая атака','Отсутствие сетевого интерфейса'],0,'Ложное положительное срабатывание ошибочно классифицирует нормальное действие как подозрительное.')])
L(40,'Защищаем рабочую станцию',
 'Защита конечного устройства включает обновления, минимальные права, локальный firewall, антивирус/EDR, контроль приложений и резервное копирование. Сетевая защита не заменяет эти меры.',
 'Антивирус обнаруживает известные и некоторые новые вредоносные признаки; EDR добавляет наблюдение и реагирование на поведение конечной точки. Ни один продукт не гарантирует полное обнаружение. Используйте обычную учётную запись для повседневной работы и проверяйте состояние агентов и обновлений.',
 'В изолированной учебной ВМ включите обновления и локальный firewall, проверьте состояние встроенной защиты и логи. Отчёт должен объяснять каждый контроль. Для учебной проверки настроек не нужно запускать вредоносные образцы.',
 'Установленный, но отключённый или устаревший агент не равен работающей защите.',[
 M('Какие меры полезны на рабочей станции?',['Обновления','Минимальные права','Постоянная работа всех с правами admin'],[0,1],'Ограничение прав уменьшает последствия, обновления закрывают известные уязвимости.'),
 C('Нужно ли контролировать состояние антивирусного агента?',['Да','Нет, установка навсегда достаточна'],0,'Агент может быть остановлен, устареть или потерять связь с управлением.'),
 O('Проверка базовой защиты ВМ.',['Подтвердить настройки и логи','Включить необходимые контроли','Определить исходное состояние'],[2,1,0],'Сначала исходные данные, затем изменение и проверка результата.'),
 C('Почему firewall на границе не отменяет локальную защиту?',['Угрозы и боковое движение возможны внутри сети','Внутри сети всегда безопасно','Локальные процессы не используют сеть'],0,'Защищать нужно и сетевой периметр, и конечные узлы.')])
L(58,'ACL: порядок имеет значение',
 'ACL разрешает или запрещает пакеты по условиям. В типичной Cisco ACL проверка идёт сверху вниз до первого совпадения, а в конце действует неявный запрет.',
 'Стандартная IPv4 ACL обычно учитывает источник; расширенная — источник, назначение, протокол и порты. Важны интерфейс и направление применения. Wildcard — обратная маска сравнения: для /24 это 0.0.0.255. Сначала сформулируйте матрицу доступов словами, затем переводите её в правила и тестируйте оба направления.',
 'Если deny ip any any стоит до permit tcp ... eq 443, разрешение HTTPS не сработает: первый запрет уже совпал. Поставьте более конкретное разрешение перед общим запретом. При stateless ACL отдельно учитывайте ответный трафик — она не становится stateful автоматически.',
 'ACL, выбирающая адреса для NAT, и ACL на интерфейсе могут иметь разное назначение.',[
 C('Что происходит после первого совпавшего правила типичной ACL?',['Применяется его действие, поиск прекращается','Всегда проверяются только следующие permit','Все правила игнорируются'],0,'Порядок сверху вниз определяет результат первого совпадения.'),
 N('Wildcard для маски 255.255.255.0?','0.0.0.255','Wildcard получается побитовым инвертированием маски в этом примере.'),
 O('Разрешите HTTPS и запретите остальное.',['Общий deny','Разрешение TCP 443','Определить источник и назначение'],[2,1,0],'Сначала условие доступа, затем конкретное разрешение до общего запрета.'),
 C('Перед permit TCP 443 стоит deny ip any any. Пройдёт ли HTTPS?',['Нет','Да, permit всегда важнее'],0,'Первое совпадение — общий deny; позднее разрешение не достигается.')])

# Module 12.
L(31,'TLS: защищаем соединение и проверяем сторону',
 'TLS защищает данные при передаче: обеспечивает конфиденциальность, целостность и аутентификацию стороны при правильной проверке сертификата. SSL — устаревшее семейство предшественников TLS.',
 'При установлении соединения согласуются параметры, проверяется сертификат и формируются ключи сеанса. Клиент проверяет имя сервера, срок действия и доверенную цепочку. Конкретный handshake зависит от версии TLS. HTTPS — HTTP поверх TLS; это не защита данных после их расшифровки на конечном устройстве.',
 'Для https://lab.test сертификат должен соответствовать lab.test, быть действительным и вести к доверенному центру. Если имя не совпало, сначала проверьте URL и конфигурацию сертификата. Если срок кажется неправильным — проверьте и время клиента. Не отключайте валидацию как постоянное решение.',
 'Замок HTTPS не гарантирует добросовестность содержимого сайта или отсутствие уязвимостей приложения.',[
 M('Что проверяет клиент в сертификате?',['Имя сервера','Срок и цепочку доверия','Цвет страницы'],[0,1],'Эти проверки устанавливают соответствие получателя и доверие к удостоверению.'),
 C('Следует ли включать SSL ради обхода ошибки современного клиента?',['Нет, нужно исправить совместимую TLS-конфигурацию','Да, SSL всегда безопаснее'],0,'Устаревший протокол не является правильным способом исправления доверия.'),
 O('Упрощённая логика TLS.',['Передача защищённых данных','Согласование и проверка стороны','Получение ключей сеанса'],[1,2,0],'Перед защищённым обменом нужно согласовать параметры и ключи.'),
 C('Сертификат выдан для other.test, а клиент открывает lab.test. Что делать?',['Исправить имя/сертификат, не обходя проверку','Считать любое шифрование достаточным','Выключить проверку навсегда'],0,'Несовпадение имени нарушает проверку ожидаемой стороны.')])
L(32,'VPN: логический канал поверх сети',
 'VPN создаёт логическое соединение поверх другой сети. Защита зависит от протокола и настройки; распространены site-to-site для площадок и remote access для пользователей.',
 'Для рабочего туннеля нужны достижимые внешние узлы, согласованные параметры и аутентификация. Внутренние подсети, маршруты, ACL и исключения NAT должны соответствовать задаче. Непересекающиеся адресные пространства упрощают маршрутизацию. Статус туннеля сам по себе не доказывает прохождение полезного трафика.',
 'Офис 192.168.10.0/24 соединяется с филиалом 192.168.20.0/24. После установления VPN проверьте трафик между разрешёнными хостами, счётчики шифрования/дешифрования и обратный путь. Если внешняя связь есть, а внутренняя нет, исследуйте маршруты и selectors.',
 'VPN не заменяет авторизацию к ресурсам и защиту подключённого устройства.',[
 C('Какой тип VPN типичен для двух офисных LAN?',['Site-to-site','Только гостевой SSID','DNS cache'],0,'Site-to-site связывает сети площадок через туннель.'),
 M('Что проверить помимо статуса Up?',['Полезный трафик внутри туннеля','Обратный маршрут','Только имя файла конфигурации'],[0,1],'Установленный туннель может не переносить нужные потоки из-за маршрутов или политик.'),
 C('Почему одинаковые подсети двух площадок создают проблему?',['Неоднозначно, куда маршрутизировать адреса','VPN обязательно отключает IPv4','Имена становятся слишком длинными'],0,'Пересекающиеся адресные пространства требуют отдельного решения, например изменения плана или трансляции.'),
 C('Туннель Up, но счётчики полезного трафика не растут. Что проверить?',['Маршруты и выбранные защищаемые подсети','Только наличие антенны','Обязательно все кабели заменить'],0,'Трафик может вообще не попадать в туннель из-за неверного маршрута или selectors.')])
L(33,'IPsec и L2TP: туннель не равен шифрованию',
 'IPsec защищает IP-трафик; IKE согласует параметры и ключи, ESP обычно обеспечивает шифрование и контроль целостности. L2TP создаёт туннель канального уровня, но сам по себе не шифрует данные.',
 'При IPsec согласуются аутентификация, алгоритмы, группы обмена, сроки и защищаемые сети. Tunnel mode инкапсулирует исходный IP-пакет; transport mode защищает его полезную нагрузку. L2TP часто комбинируют с IPsec. Для диагностики различайте сбой переговоров и сбой передачи данных после их завершения.',
 'Если одна сторона использует сеть 192.168.10.0/24 ↔ 192.168.20.0/24, другая должна описывать соответствующие обратные направления. Ошибка shared secret мешает аутентификации, ошибка selectors — выбору полезного трафика. Сверяйте логи, не публикуя реальные ключи.',
 'Нельзя объявлять любой L2TP-туннель защищённым шифрованием без дополнительного механизма.',[
 C('Какова роль IKE?',['Согласование параметров и ключей','Выдача DHCP-адресов любому клиенту','Только сжатие изображений'],0,'IKE выполняет согласование для IPsec и аутентификацию сторон.'),
 C('Шифрует ли L2TP сам по себе?',['Нет','Да, всегда'],0,'L2TP — туннелирование; для защиты его часто объединяют с IPsec.'),
 M('Какие параметры важно согласовать?',['Аутентификацию','Защищаемые подсети','Обязательно одинаковые имена устройств'],[0,1],'Параметры безопасности и selectors должны быть совместимы.'),
 C('Пользователь считает L2TP без IPsec шифрованным VPN. Что уточнить?',['Туннелирование и шифрование — разные функции','Любой туннель автоматически шифрует всё','Нужно только сменить DNS'],0,'Без дополнительной защиты L2TP не обеспечивает шифрование.')])
L(35,'Кто вы и что вам разрешено?',
 'Аутентификация проверяет личность, авторизация определяет разрешённые действия, аудит фиксирует выполненные действия. Успешный вход не означает право доступа ко всем ресурсам.',
 'Пользователь подтверждает личность учётными данными, затем роли и политики определяют доступ. Принцип минимальных прав ограничивает возможности необходимым набором. При изменении роли или увольнении права и активные сеансы нужно пересматривать и отзывать по процедуре.',
 'Студент успешно вошёл в платформу — это аутентификация. Он видит свои работы, но не может выставлять оценки — это авторизация. Запись о попытке изменения оценки относится к аудиту. Скрытие кнопки в браузере не заменяет серверную проверку роли.',
 'Нельзя считать проверку прав выполненной только потому, что пользователь прошёл login.',[
 C('Проверка пароля относится к чему?',['Аутентификации','Только маршрутизации','Назначению VLAN'],0,'Учётные данные подтверждают заявленную личность.'),
 C('Запрет студенту менять оценку — это…',['Авторизация','Разрешение имени','Инкапсуляция'],0,'Политика определяет допустимые действия уже известного пользователя.'),
 M('Что нужно при изменении обязанностей сотрудника?',['Пересмотреть роли','Отозвать ненужные доступы','Всегда оставить все старые права'],[0,1],'Права должны соответствовать текущим обязанностям, а не накапливаться бессрочно.'),
 C('Пользователь вошёл, но получает запрет доступа к чужой работе. Что это может означать?',['Авторизация работает согласно политике','Пароль обязательно неверен','Сеть обязательно выключена'],0,'Успешная аутентификация совместима с ограничениями на конкретные ресурсы.')])
L(36,'Пароль и второй фактор',
 'Пароль — фактор знания. Многофакторная аутентификация сочетает разные категории: знание, владение или биометрические свойства. Два пароля не становятся двумя независимыми факторами.',
 'Используйте длинные уникальные пароли и безопасный менеджер. Ограничение попыток, мониторинг и защита восстановления дополняют MFA. Приложение-аутентификатор или аппаратный ключ может подтверждать владение. Стойкость к фишингу зависит от метода; одноразовый код тоже может быть перехвачен социальной инженерией.',
 'Пароль плюс аппаратный ключ — сочетание знания и владения. Пароль плюс второй секретный вопрос остаются двумя проверками знания. Резервные коды и восстановление нужно хранить и контролировать так, чтобы они не обходили основную защиту.',
 'Нельзя обещать абсолютную защиту только от включения любой разновидности MFA.',[
 C('Пароль и второй пароль — это два разных фактора?',['Нет','Да'],0,'Оба относятся к категории знания.'),
 M('Какие меры полезны для паролей?',['Уникальность для разных сервисов','Достаточная длина','Один общий пароль на всех'],[0,1],'Уникальность ограничивает последствия утечки одного сервиса.'),
 C('Аппаратный ключ относится к какой категории?',['Владение','Только знание','Номер сетевого порта'],0,'Пользователь доказывает наличие устройства или соответствующего секрета в нём.'),
 C('Почему нужно защищать восстановление аккаунта?',['Оно может стать обходным путём MFA','Оно никак не влияет на доступ','Резервные коды можно публиковать'],0,'Слабое восстановление снижает защиту основного входа.')])
L(39,'Удалённый доступ без лишних прав',
 'VPN для удалённого доступа подключает пользователя к разрешённым ресурсам организации. Надёжная схема сочетает проверку личности, MFA, контроль устройства, ограничение маршрутов и журналирование.',
 'Определите роли и требуемые сервисы, примените минимальные права и срок сеанса. Split tunnel направляет через VPN выбранный трафик, full tunnel — более широкий набор по политике; выбор связан с требованиями и рисками. Проверьте DNS, маршруты, доступность разрешённых и блокировку лишних ресурсов.',
 'Сотруднику поддержки нужен HTTPS к приложению и SSH к выделенному серверу, но не ко всей серверной. После подключения проверьте оба разрешения и отрицательный сценарий. При увольнении отзывают доступ и активные сеансы, а не только удаляют ярлык VPN.',
 'Нахождение «внутри VPN» не должно автоматически давать доверие ко всем системам.',[
 M('Что дополнить к удалённому VPN?',['MFA','Ограничение ресурсов по роли','Полный постоянный доступ всем'],[0,1],'Туннель защищает канал, а доступ определяют политики и личность.'),
 C('Что означает split tunnel?',['Через VPN идёт выбранный политикой трафик','VPN не имеет аутентификации','Шифрование всегда выключено'],0,'Разделение относится к маршрутизации трафика, а не автоматическому отключению защиты.'),
 O('Организация доступа подрядчика.',['Отозвать доступ после завершения','Определить задачи и минимальные права','Проверить подключение и ограничения'],[1,2,0],'Доступ имеет цель, проверку и контролируемое окончание.'),
 C('После увольнения учётная запись удалена, но сеанс ещё активен. Что требуется?',['Отозвать активные сессии согласно процедуре','Считать удаление ярлыка достаточным','Выключить мониторинг'],0,'Уже установленный доступ может требовать отдельного завершения.')])

# Module 13.
L(12,'Соединяем корпоративную сеть с облаком',
 'Гибридная сеть объединяет локальную инфраструктуру с облачными ресурсами через защищённые соединения и согласованные адресацию, маршрутизацию, DNS и управление доступом.',
 'Проверьте непересечение подсетей, пути в обе стороны и разрешённые сервисы. Используйте VPN, выделенную связь или HTTPS в зависимости от архитектуры. Согласуйте идентификацию, правила cloud firewall, журналы, доступность и резервный сценарий. Подключение к облаку не переносит всю ответственность провайдеру.',
 'LAN 192.168.10.0/24 подключается к облачной 10.20.0.0/16 через VPN. Маршрут к облаку должен быть на офисной стороне, обратный — в облаке. DNS должен возвращать нужный частный адрес там, где требуется private access.',
 'Две одинаковые подсети по разные стороны туннеля создают неоднозначность и не исправляются одним фактом Up.',[
 C('Что проверить до связи двух площадок?',['Непересечение адресных пространств','Только названия организаций','Только заставку сервера'],0,'Пересечение подсетей осложняет маршрутизацию между ними.'),
 M('Какие настройки должны быть согласованы?',['Маршруты в обе стороны','DNS и права доступа','Обязательное разрешение всех портов Интернету'],[0,1],'Гибридное подключение включает сеть, имена и ограничения.'),
 O('Проверка гибридного доступа.',['Проверить прикладной сервис и ограничения','Проверить канал и маршруты','Проверить нужное разрешение имени'],[1,2,0],'Сначала достижимость, затем имя, затем целевое действие.'),
 C('Офис видит облачный узел, но ответ не возвращается. Что проверить?',['Обратный маршрут и правила облачной стороны','Только питание мыши','Обязательно сменить имя VLAN'],0,'Нужны двусторонние маршруты и разрешения.')])
L(13,'IoT — сеть множества устройств',
 'Интернет вещей объединяет датчики, исполнительные устройства, шлюзы и сервисы обработки данных. Архитектура учитывает ограниченные ресурсы, способы связи, управление устройствами и безопасность.',
 'Датчик может передавать данные через локальный шлюз к платформе. Используются разные радиоканалы и прикладные протоколы, поэтому важны совместимость и питание. Каждое устройство нужно учитывать, обновлять и ограничивать по доступу. Для сегментации выделяют IoT-сеть и разрешают только нужные потоки.',
 'Датчик температуры отправляет показания шлюзу, тот — серверу мониторинга. Датчику не нужен SSH ко всем рабочим станциям. Если связь с облаком пропала, заранее определите поведение: буферизация, локальная сигнализация или безопасное состояние.',
 '«Маленький датчик» тоже может стать точкой входа и источником утечки.',[
 C('Какую роль часто выполняет IoT-шлюз?',['Связывает устройства с сервисами и преобразует обмен','Отменяет необходимость защиты','Всегда является только принтером'],0,'Шлюз может агрегировать и передавать данные между разными протоколами и сетями.'),
 M('Что нужно для эксплуатации IoT?',['Инвентаризация','Обновления и контроль доступа','Заводские общие пароли навсегда'],[0,1],'Большое число устройств требует управляемого жизненного цикла.'),
 C('Нужен ли датчику полный доступ к офисной LAN?',['Нет, разрешают необходимые потоки','Да, обязательно'],0,'Сегментация ограничивает последствия компрометации.'),
 C('Что предусмотреть при потере облачного соединения?',['Определённое безопасное локальное поведение','Ничего, сеть никогда не теряется','Неограниченный доступ всем'],0,'Устройство должно вести себя предсказуемо при недоступности внешних зависимостей.')])
L(43,'Тенденции безопасности: принципы вместо лозунгов',
 'Развитие безопасности связано с проверкой доступа по контексту, защитой облаков и цепочек поставок, наблюдением конечных устройств и автоматизацией реакции. Конкретные инструменты оценивают по угрозам и результатам.',
 'Zero Trust отказывается от безусловного доверия только по расположению в сети. Используются проверка личности и устройства, минимальные права и наблюдение. Автоматизация ускоряет реакцию, но ошибочное правило может масштабировать ущерб. Для новых средств задавайте измеримые критерии, доступ к данным и возможность отката.',
 'Перед автоматической блокировкой учётных записей по аномалии сначала проверьте сигнал на исторических событиях и примените режим уведомлений. Затем ограничьте область автоматического действия и сохраните ручной пересмотр. Название технологии не является доказательством эффективности.',
 'Zero Trust — подход к архитектуре и проверкам, а не одна волшебная коробка.',[
 C('Что означает отказ от безусловного внутреннего доверия?',['Доступ проверяется по личности, устройству и контексту','Все пользователи всегда блокируются','VPN автоматически разрешает всё'],0,'Расположение в LAN само по себе не даёт всех полномочий.'),
 M('Что оценить перед автоматической реакцией?',['Качество сигналов','Возможность отката','Только название продукта'],[0,1],'Неверный автоматический вывод может быстро повлиять на много пользователей.'),
 O('Безопасное внедрение автоматической блокировки.',['Ограниченный рабочий запуск','Проверка исторических событий','Режим уведомлений без блокировки'],[1,2,0],'Сначала оценивают качество, затем наблюдают и лишь после этого включают ограниченное действие.'),
 C('Как подтвердить пользу нового средства защиты?',['Измеримыми результатами в своём сценарии','Только рекламным названием','Отказом от всех существующих логов'],0,'Решение должно соответствовать рискам и давать проверяемый результат.')])
L(44,'Кибершпионаж и взлом IoT',
 'Кибершпионаж направлен на скрытое получение информации и может продолжаться длительно. Компрометация IoT-устройства создаёт риск доступа к данным, наблюдения или продвижения в другие сегменты.',
 'Угрозы усиливают заводские пароли, отсутствие обновлений, открытые интерфейсы управления и избыточные сетевые права. Ограничивайте исходящие соединения, отделяйте IoT от рабочих станций, наблюдайте необычный экспорт данных. Срабатывания проверяйте по контексту и сохраняйте доказательства.',
 'Камера внезапно отправляет большой объём данных незнакомому внешнему узлу. Сравните с обычным поведением, проверьте обновления и разрешённые сервисы. При подтверждении действуйте по плану реагирования: ограничьте связь, сохраните данные расследования и восстановите доверенную конфигурацию.',
 'Большой объём трафика — сигнал, но не самостоятельное доказательство кражи данных.',[
 C('Что ограничит боковое движение от взломанного датчика?',['Сегментация и минимальные сетевые права','Доступ ко всем серверам','Отключение журналов'],0,'Устройство не должно получать произвольный доступ к другим активам.'),
 M('Какие настройки повышают риск IoT?',['Заводские пароли','Открытое управление из Интернета','Контроль обновлений'],[0,1],'Общие пароли и доступное управление упрощают компрометацию.'),
 O('Разбор подозрительного экспорта данных.',['Подтвердить вывод и отреагировать по плану','Сохранить наблюдения','Сопоставить с нормой и разрешёнными службами'],[1,2,0],'Сначала доказательства и контекст, затем обоснованная реакция.'),
 C('Почему кибершпионаж может быть трудно заметить?',['Он может использовать длительный малозаметный доступ','Он всегда полностью выключает сеть','Он невозможен в IoT'],0,'Не всякая атака проявляется явным отказом; нужны наблюдение и контроль доступа.')])
L(45,'Разделённая ответственность в облаке',
 'Облачная безопасность разделяется между провайдером и клиентом. Граница зависит от модели IaaS, PaaS или SaaS и договора; клиент остаётся ответственным за свои данные, идентификацию и разрешённые настройки.',
 'В IaaS клиент обычно управляет гостевой ОС и приложениями, провайдер — физической инфраструктурой. В PaaS часть платформы обслуживает провайдер; в SaaS он ведёт приложение, но клиент управляет пользователями и использованием данных. Для каждого сервиса проверьте конкретную матрицу обязанностей, журналирование и восстановление.',
 'Если администратор сделал облачное хранилище публичным, наличие защищённого дата-центра не отменит утечку. Если клиент управляет ВМ IaaS, он должен обновлять её ОС в пределах своей ответственности. Нельзя переносить обязанности из одного сервиса на другой по аналогии.',
 '«Это в облаке» не означает «за всё отвечает провайдер».',[
 C('Кто обычно обновляет гостевую ОС собственной ВМ IaaS?',['Клиент','Любой соседний пользователь','DNS автоматически'],0,'В IaaS управление гостевой ОС обычно лежит на клиенте.'),
 M('Что остаётся важным для клиента SaaS?',['Управление пользователями','Права доступа к данным','Полный отказ от контроля'],[0,1],'Даже управляемое приложение требует корректного управления идентификацией и данными.'),
 C('Где уточнять границу ответственности?',['В документации и условиях конкретного сервиса','Только по слову облако','В имени VLAN'],0,'Модели различаются, а конкретные обязанности задаются сервисом.'),
 C('Хранилище случайно открыто всем. Защищённый дата-центр устраняет риск?',['Нет, ошибка доступа остаётся','Да, данные автоматически закрыты'],0,'Физическая защита не исправляет публичную политику доступа.')])
L(46,'Риски облачного хранения и передачи',
 'Основные облачные риски — ошибочные разрешения, утечки учётных данных, потеря доступа или данных, недоступность зависимости и перехват при неправильной защите канала. Риск зависит от архитектуры и управления.',
 'Инвентаризируйте данные и пути передачи, определите владельцев и допустимый доступ. Применяйте TLS, шифрование хранения, минимальные роли и контроль ключей. Планируйте резервирование, экспорт и восстановление. Оценивайте не только утечку, но и возможность продолжить работу при недоступности сервиса.',
 'Файл может быть зашифрован на диске провайдера, но оставаться доступным любому через публичную ссылку. Если ключ администратора опубликован в репозитории, требуется отзыв и замена, а не только удаление строки из последнего файла.',
 'Шифрование хранения не защищает от чтения через ошибочно разрешённый API.',[
 C('Публичная ссылка открывает зашифрованный на диске файл. Есть ли риск утечки?',['Да','Нет, шифрование диска всё предотвращает'],0,'Сервис законно расшифрует файл для любого, кому разрешён доступ по этой ссылке.'),
 M('Какие риски стоит учитывать?',['Недоступность сервиса','Утечку ключа','Только цвет веб-интерфейса'],[0,1],'Безопасность включает доступность и контроль учётных данных.'),
 O('Действия после обнаружения утёкшего ключа.',['Проверить журналы и последствия','Отозвать скомпрометированный ключ','Выдать новый с нужными правами'],[1,2,0],'Ключ сначала прекращают принимать, затем восстанавливают контролируемый доступ и расследуют последствия.'),
 C('Почему удаления ключа из последнего коммита недостаточно?',['Он мог сохраниться в истории и быть скопирован','Ключи никогда не читаются','История автоматически исчезает'],0,'Секрет нужно считать раскрытым и отозвать.')])
L(47,'Защищаем облачное хранилище',
 'Защита хранилища сочетает закрытый доступ по умолчанию, минимальные роли, защищённую передачу, управление ключами, журналирование и проверяемое резервирование.',
 'Разделяйте права чтения, записи и администрирования. Используйте краткоживущие ссылки или учётные данные там, где это подходит, ограничивайте срок и ресурс. Включайте версионирование и отдельные копии по требованиям; удаление или ransomware может затронуть доступные тому же аккаунту копии. Периодически проверяйте восстановление.',
 'Студенту нужен доступ к собственной работе, преподавателю — к работам своей области ответственности. Приватное хранилище и серверная проверка владельца перед скачиванием реализуют это лучше, чем публичные постоянные URL. Просроченная временная ссылка должна перестать давать доступ.',
 'Одно наличие резервного файла не подтверждает, что его можно восстановить и прочитать.',[
 C('Какой доступ разумен по умолчанию для работ студентов?',['Закрытый, с проверкой прав','Публичный для всех','Неограниченная запись всем'],0,'Доступ должен соответствовать владельцу и роли проверяющего.'),
 M('Что ограничивает риск временной ссылки?',['Срок действия','Область разрешённого ресурса','Публикация ключа администратора'],[0,1],'Ссылка должна давать минимальный и ограниченный по времени доступ.'),
 O('Проверяем резервную копию.',['Сравнить целостность и доступность результата','Восстановить в отдельную среду','Выбрать нужную точку восстановления'],[2,1,0],'Практическое восстановление подтверждает пригодность копии.'),
 C('Что лучше подтверждает защиту доступа к файлу?',['Тест владельца и отказ постороннему','Только надпись private в отчёте','Только расширение .pdf'],0,'Нужны реальные положительные и отрицательные проверки авторизации.')])
L(48,'Новая технология — новые зависимости',
 'Новые сетевые технологии меняют поверхность атаки, способы идентификации, управления ключами и наблюдения. Требования безопасности должны обновляться вместе с архитектурой.',
 'Автоматизация, облачные API, программно управляемые сети и массовое IoT увеличивают число зависимостей и привилегированных интерфейсов. Рассматривайте угрозы управления, ошибочной конфигурации и цепочки поставок. Для внедрения нужны сегментация, аудит, проверка прав, тестирование и откат.',
 'Центральный контроллер быстро распространяет настройки. Это удобно, но компрометация его учётной записи или ошибка шаблона затронет много узлов. Ограничьте роли, тестируйте шаблон на малой группе, сохраняйте версии и наблюдайте изменения.',
 'Автоматическая конфигурация не становится правильной только потому, что она применяется одинаково.',[
 C('Почему центральный контроллер требует особой защиты?',['Его права могут влиять на много устройств','Он не имеет сетевого доступа','Он отменяет аутентификацию'],0,'Масштаб полномочий увеличивает возможные последствия ошибки или компрометации.'),
 M('Что оценивать у новой технологии?',['Поверхность атаки','Наблюдаемость и откат','Только модное название'],[0,1],'Архитектурные свойства важнее названия решения.'),
 O('Развёртывание нового шаблона конфигурации.',['Расширить после проверки','Проверить в тестовой среде','Применить к небольшой группе'],[1,2,0],'Поэтапность ограничивает последствия и позволяет заметить ошибку.'),
 C('Ошибка автоматизации одинаково открыла доступ на ста узлах. Что показывает пример?',['Автоматизация масштабирует и ошибки','Автоматизация всегда исключает риски','Нужны только новые кабели'],0,'Нужны контроль изменений, ограничение области и возможность отката.')])

# Module 14.
L(42,'Резервная копия должна восстанавливаться',
 'Резервное копирование сохраняет данные и конфигурации для восстановления после отказа, ошибки или атаки. RPO определяет допустимую потерю данных по времени, RTO — допустимую длительность восстановления.',
 'Определите критичные объекты, частоту, срок хранения, отдельное размещение и права. Копии должны пережить отказ или компрометацию основной среды: полезны разные носители и отдельная/offline или неизменяемая копия по требованиям. Регулярно проверяйте восстановление, зависимости и целостность.',
 'При RPO 24 часа ежедневная успешная копия может соответствовать требованию, если фактический разрыв не превышает 24 часа. RTO 2 часа требует проверки, что весь сервис с настройками и данными восстанавливается за это время. Одного быстрого копирования файла недостаточно.',
 'RAID, репликация и snapshot не всегда заменяют независимый бэкап: логическая ошибка может распространиться на все копии.',[
 C('Что измеряет RPO?',['Допустимую потерю данных во времени','Число VLAN','Скорость процессора'],0,'RPO задаёт, к какой давности данных допустимо вернуться.'),
 N('RTO 2 часа: сколько минут составляет целевое время восстановления?','120','2×60=120 минут на восстановление целевой функции.'),
 M('Что нужно проверить у резервирования?',['Успешность восстановления','Независимость копии от основного сбоя','Только наличие имени backup.zip'],[0,1],'Копия полезна, если переживает нужный сценарий отказа и пригодна к восстановлению.'),
 C('Файл бэкапа существует, но никогда не восстанавливался. Можно считать план проверенным?',['Нет','Да'],0,'Нужно практическое восстановление с измерением времени и проверкой результата.')])
L(60,'Итог: диагностируем всю цепочку',
 'Комплексная настройка связывает адресный план, VLAN, маршруты, службы, ограничения, VPN, мониторинг и восстановление. Диагностика проверяет предпосылки по порядку и подтверждает каждое исправление.',
 'Начните с физического состояния, VLAN и IP клиента. Затем проверьте шлюз, маршруты в обе стороны, DHCP/DNS и целевую службу. Добавляйте ACL и VPN с положительными и отрицательными тестами. Зафиксируйте схему, конфигурацию и таблицу «ожидалось/получено», сохраните копию и план отката.',
 'В проекте VLAN10/20 и серверная VLAN30 получают непересекающиеся /24, шлюзы .1, сервер DNS/HTTP .2 в VLAN30. Клиенты должны получать корректные параметры, открывать сервер по имени, не иметь запрещённого SSH, а удалённая площадка — достигать только разрешённых ресурсов через VPN.',
 'Одновременное случайное изменение многих параметров может скрыть причину и создать новые сбои.',[
 O('Базовый порядок комплексной проверки.',['Проверить службы, ACL и VPN','Проверить канал, VLAN и адресацию','Проверить шлюзы и маршруты'],[1,2,0],'Каждый следующий уровень зависит от исправности предыдущих предпосылок.'),
 M('Что должно быть в итоговом отчёте?',['Схема и адресный план','Положительные и отрицательные тесты','Только скриншот без пояснений'],[0,1],'Отчёт должен позволять воспроизвести и оценить результат.'),
 C('После исправления DNS сайт открылся. Что сделать дальше?',['Повторить контрольные проверки и зафиксировать изменение','Ничего не записывать','Отключить все ограничения навсегда'],0,'Проверка регрессий и документация закрепляют результат.'),
 C('Какое условие лучше подтверждает готовность корпоративной сети?',['Разрешённые функции работают, запреты действуют, восстановление проверено','Один ping прошёл','Все правила удалены'],0,'Готовность включает функциональность, ограничения и эксплуатационную устойчивость.')])
